import i18n from 'i18next';
import { initReactI18next } from 'react-i18next';
import LanguageDetector from 'i18next-browser-languagedetector';

i18n
  .use(LanguageDetector)
  .use(initReactI18next)
  .init({
    fallbackLng: 'en', // Onnumey puriyala na English
    resources: {
      en: {
        translation: {
          app_name: "Agro Zenith",
          Welcome: "Welcome",
          active_alerts: "Active Alerts",
          risk_analysis: "Risk Analysis",
          detect_btn: "Analyze Crop",
          chat_placeholder: "Ask about fertilizers...",
          soil_btn: "Check Soil Health",
          market_movers: "Today's Market Movers",
          confluence: "Confluence Score",
          crops_tracked: "Crops Tracked",
          farm_plots: "Farm Plots",
          "Medium Risk": "Medium Risk",
          lang_name: "English"
        }
      },
      ta: {
        translation: {
          app_name: "அக்ரோ ஜெனித்",
          Welcome: "வணக்கம்",
          active_alerts: "செயலில் உள்ள பண்ணை எச்சரிக்கைகள்",
          risk_analysis: "ஆபத்து பகுப்பாய்வு",
          detect_btn: "பயிரை ஆய்வு செய்",
          chat_placeholder: "உரங்களைப் பற்றி கேளுங்கள்...",
          soil_btn: "மண் ஆரோக்கியம்",
          confluence: "கலவமைப்பு மதிப்பெண்",
          market_movers: "இன்றைய சந்தை நிலவரம்",
          crops_tracked: "பயிர்கள் கண்காணிப்பு",
          farm_plots: "பண்ணை நிலங்கள்",
          "Medium Risk": "மிதமான ஆபத்து",
          lang_name: "தமிழ்"
        }
      },
      hi: {
        translation: {
          app_name: "एग्रो जेनिथ",
          Welcome: "नमस्ते",
          active_alerts: "सक्रिय अलर्ट",
          risk_analysis: "जोखिम विश्लेषण",
          detect_btn: "फसल की जाँच करें",
          chat_placeholder: "उर्वरकों के बारे में पूछें...",
          soil_btn: "मिट्टी का स्वास्थ्य",
          confluence: "संयोजन स्कोर",
          market_movers: "आज के बाजार के उत्तेजित पदार्थ",
          crops_tracked: "ट्रैक की गई फसलें",
          farm_plots: "खेत के भूखंड",
          "Medium Risk": "मध्यम जोखिम",
          lang_name: "हिंदी"
        }
      }
    },
    fallbackLng: 'en',
    interpolation: { escapeValue: false }
  });

export default i18n;
